"use client";

import { motion, useReducedMotion } from "framer-motion";

export function PrimaryButton({ children }: { children: React.ReactNode }) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.button
      whileHover={shouldReduceMotion ? undefined : { y: -2 }}
      whileTap={{ scale: 0.96, y: 0 }}
      transition={{ type: "spring", stiffness: 500, damping: 30 }}
      className="group relative inline-flex items-center justify-center overflow-hidden rounded-lg bg-zinc-900 px-5 py-2.5 text-sm font-medium text-white dark:text-zinc-900 shadow-[0_1px_2px_rgba(24,24,27,0.3)] transition-[box-shadow,background-color] duration-300 hover:bg-zinc-800 hover:shadow-[0_12px_24px_-8px_rgba(24,24,27,0.65)] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-zinc-900 active:bg-zinc-950 dark:bg-zinc-50 dark:shadow-[0_1px_2px_rgba(250,250,250,0.35)] dark:hover:bg-zinc-200 dark:hover:shadow-[0_12px_24px_-8px_rgba(250,250,250,0.55)] dark:focus-visible:outline-zinc-50 dark:active:bg-zinc-300"
    >
      <span
        aria-hidden
        className="pointer-events-none absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/30 to-transparent transition-transform duration-700 ease-out group-hover:translate-x-full motion-reduce:hidden"
      />
      <span className="relative">{children}</span>
    </motion.button>
  );
}
